74	/// Information on loadable part of the file.
75	struct SegmentInfo {
76	  uint64_t Address;           /// Address of the segment in memory.
77	  uint64_t Size;              /// Size of the segment in memory.
78	  uint64_t FileOffset;        /// Offset in the file.
79	  uint64_t FileSize;          /// Size in file.
80	  uint64_t Alignment;         /// Alignment of the segment.
81	  bool IsExecutable;          /// Is the executable bit set on the Segment?
82	  bool IsWritable;            /// Is the segment writable.
83	
84	  void print(raw_ostream &OS) const {
85	    OS << "SegmentInfo { Address: 0x" << Twine::utohexstr(Address)
86	       << ", Size: 0x" << Twine::utohexstr(Size) << ", FileOffset: 0x"
87	       << Twine::utohexstr(FileOffset) << ", FileSize: 0x"
88	       << Twine::utohexstr(FileSize) << ", Alignment: 0x"
89	       << Twine::utohexstr(Alignment) << ", " << (IsExecutable ? "x" : "")
90	       << (IsWritable ? "w" : "") << " }";
91	  };
92	};
