117	/// Filter iterator.
118	template <typename ItrType,
119	          typename PredType = std::function<bool(const ItrType &)>>
120	class FilterIterator {
121	  using inner_traits = std::iterator_traits<ItrType>;
122	  using Iterator = FilterIterator;
123	
124	  PredType Pred;
125	  ItrType Itr, End;
126	
127	  void prev() {
128	    while (!Pred(--Itr))
129	      ;
130	  }
131	  void next() {
132	    ++Itr;
133	    nextMatching();
134	  }
135	  void nextMatching() {
136	    while (Itr != End && !Pred(Itr))
137	      ++Itr;
138	  }
139	
140	public:
141	  using iterator_category = std::bidirectional_iterator_tag;
142	  using value_type = typename inner_traits::value_type;
143	  using difference_type = typename inner_traits::difference_type;
144	  using pointer = typename inner_traits::pointer;
145	  using reference = typename inner_traits::reference;
146	
147	  Iterator &operator++() { next(); return *this; }
148	  Iterator &operator--() { prev(); return *this; }
149	  Iterator operator++(int) { auto Tmp(Itr); next(); return Tmp; }
150	  Iterator operator--(int) { auto Tmp(Itr); prev(); return Tmp; }
151	  bool operator==(const Iterator &Other) const { return Itr == Other.Itr; }
152	  bool operator!=(const Iterator &Other) const { return !operator==(Other); }
153	  reference operator*() { return *Itr; }
154	  pointer operator->() { return &operator*(); }
155	  FilterIterator(PredType Pred, ItrType Itr, ItrType End)
156	      : Pred(Pred), Itr(Itr), End(End) {
157	    nextMatching();
158	  }
159	};
