435	  /// Return BinaryFunction containing a given \p Address or nullptr if
436	  /// no registered function contains the \p Address.
437	  ///
438	  /// In a binary a function has somewhat vague  boundaries. E.g. a function can
439	  /// refer to the first byte past the end of the function, and it will still be
440	  /// referring to this function, not the function following it in the address
441	  /// space. Thus we have the following flags that allow to lookup for
442	  /// a function where a caller has more context for the search.
443	  ///
444	  /// If \p CheckPastEnd is true and the \p Address falls on a byte
445	  /// immediately following the last byte of some function and there's no other
446	  /// function that starts there, then return the function as the one containing
447	  /// the \p Address. This is useful when we need to locate functions for
448	  /// references pointing immediately past a function body.
449	  ///
450	  /// If \p UseMaxSize is true, then include the space between this function
451	  /// body and the next object in address ranges that we check.
452	  BinaryFunction *getBinaryFunctionContainingAddress(uint64_t Address,
453	                                                     bool CheckPastEnd = false,
454	                                                     bool UseMaxSize = false);
455	  const BinaryFunction *
456	  getBinaryFunctionContainingAddress(uint64_t Address,
457	                                     bool CheckPastEnd = false,
458	                                     bool UseMaxSize = false) const {
459	    return const_cast<BinaryContext *>(this)
460	        ->getBinaryFunctionContainingAddress(Address, CheckPastEnd, UseMaxSize);
461	  }
