476	  /// Return JumpTable containing a given \p Address.
477	  JumpTable *getJumpTableContainingAddress(uint64_t Address) {
478	    auto JTI = JumpTables.upper_bound(Address);
479	    if (JTI == JumpTables.begin())
480	      return nullptr;
481	    --JTI;
482	    if (JTI->first + JTI->second->getSize() > Address)
483	      return JTI->second;
484	    if (JTI->second->getSize() == 0 && JTI->first == Address)
485	      return JTI->second;
486	    return nullptr;
487	  }
