492	  unsigned getDWARFEncodingSize(unsigned Encoding) {
493	    if (Encoding == dwarf::DW_EH_PE_omit)
494	      return 0;
495	    switch (Encoding & 0x0f) {
496	    default:
497	      llvm_unreachable("unknown encoding");
498	    case dwarf::DW_EH_PE_absptr:
499	    case dwarf::DW_EH_PE_signed:
500	      return AsmInfo->getCodePointerSize();
501	    case dwarf::DW_EH_PE_udata2:
502	    case dwarf::DW_EH_PE_sdata2:
503	      return 2;
504	    case dwarf::DW_EH_PE_udata4:
505	    case dwarf::DW_EH_PE_sdata4:
506	      return 4;
507	    case dwarf::DW_EH_PE_udata8:
508	    case dwarf::DW_EH_PE_sdata8:
509	      return 8;
510	    }
511	  }
