840	  /// Fold \p Alignment into the running max for the main code section (when
841	  /// \p InMainSection) and/or the cold code section (when \p InColdSection),
842	  /// reflecting which output section(s) the object is emitted into. Safe to
843	  /// call concurrently.
844	  void updateMaxCodeAlignment(uint16_t Alignment, bool InMainSection,
845	                              bool InColdSection) {
846	    auto AtomicMax = [](std::atomic<uint16_t> &Max, uint16_t Value) {
847	      uint16_t Cur = Max.load(std::memory_order_relaxed);
848	      while (Value > Cur &&
849	             !Max.compare_exchange_weak(Cur, Value, std::memory_order_relaxed))
850	        ;
851	    };
852	    if (InMainSection)
853	      AtomicMax(MaxMainCodeAlignment, Alignment);
854	    if (InColdSection)
855	      AtomicMax(MaxColdCodeAlignment, Alignment);
856	  }
