966	  /// Iterate over all BinaryData associated with the given \p Section.
967	  iterator_range<FilteredBinaryDataConstIterator>
968	  getBinaryDataForSection(const BinarySection &Section) const {
969	    auto Begin = BinaryDataMap.lower_bound(Section.getAddress());
970	    if (Begin != BinaryDataMap.begin())
971	      --Begin;
972	    auto End = BinaryDataMap.upper_bound(Section.getEndAddress());
973	    auto pred = [&Section](const binary_data_const_iterator &Itr) -> bool {
974	      return Itr->second->getSection() == Section;
975	    };
976	    return make_range(FilteredBinaryDataConstIterator(pred, Begin, End),
977	                      FilteredBinaryDataConstIterator(pred, End, End));
978	  }
