1476	  /// Calculate the size of the instruction \p Inst optionally using a
1477	  /// user-supplied emitter for lock-free multi-thread work. MCCodeEmitter is
1478	  /// not thread safe and each thread should operate with its own copy of it.
1479	  uint64_t
1480	  computeInstructionSize(const MCInst &Inst,
1481	                         const MCCodeEmitter *Emitter = nullptr) const {
1482	    if (std::optional<uint32_t> Size = MIB->getSize(Inst))
1483	      return *Size;
1484	
1485	    if (MIB->isPseudo(Inst))
1486	      return 0;
1487	
1488	    if (std::optional<uint32_t> Size = MIB->getInstructionSize(Inst))
1489	      return *Size;
1490	
1491	    if (!Emitter)
1492	      Emitter = this->MCE.get();
1493	    SmallString<256> Code;
1494	    SmallVector<MCFixup, 4> Fixups;
1495	    Emitter->encodeInstruction(Inst, Code, Fixups, *STI);
1496	    return Code.size();
1497	  }
