1499	  /// Compute the native code size for a range of instructions.
1500	  /// Note: this can be imprecise wrt the final binary since happening prior to
1501	  /// relaxation, as well as wrt the original binary because of opcode
1502	  /// shortening.MCCodeEmitter is not thread safe and each thread should operate
1503	  /// with its own copy of it.
1504	  template <typename Itr>
1505	  uint64_t computeCodeSize(Itr Beg, Itr End,
1506	                           const MCCodeEmitter *Emitter = nullptr) const {
1507	    uint64_t Size = 0;
1508	    while (Beg != End) {
1509	      if (!MIB->isPseudo(*Beg))
1510	        Size += computeInstructionSize(*Beg, Emitter);
1511	      ++Beg;
1512	    }
1513	    return Size;
1514	  }
