915	const MCSymbol *
916	BinaryContext::getOrCreateJumpTable(BinaryFunction &Function, uint64_t Address,
917	                                    JumpTable::JumpTableType Type) {
918	  // Two fragments of same function access same jump table
919	  if (JumpTable *JT = getJumpTableContainingAddress(Address)) {
920	    assert(JT->Type == Type && "jump table types have to match");
921	    assert(Address == JT->getAddress() && "unexpected non-empty jump table");
922	
923	    if (llvm::is_contained(JT->Parents, &Function))
924	      return JT->getFirstLabel();
925	
926	    // Prevent associating a jump table to a specific fragment twice.
927	    auto isSibling = std::bind(&BinaryContext::areRelatedFragments, this,
928	                               &Function, std::placeholders::_1);
929	    assert(llvm::all_of(JT->Parents, isSibling) &&
930	           "cannot reuse jump table of a different function");
931	    (void)isSibling;
932	    if (opts::Verbosity > 2) {
933	      this->outs() << "BOLT-INFO: multiple fragments access the same jump table"
934	                   << ": " << *JT->Parents[0] << "; " << Function << '\n';
935	      JT->print(this->outs());
936	    }
937	    if (JT->Parents.size() == 1)
938	      JT->Parents.front()->setHasIndirectTargetToSplitFragment(true);
939	    Function.setHasIndirectTargetToSplitFragment(true);
940	    // Duplicate the entry for the parent function for easy access
941	    JT->Parents.push_back(&Function);
942	    Function.JumpTables.emplace(Address, JT);
943	    return JT->getFirstLabel();
944	  }
945	
946	  // Reuse the existing symbol if possible.
947	  MCSymbol *JTLabel = nullptr;
948	  if (BinaryData *Object = getBinaryDataAtAddress(Address)) {
949	    if (!isInternalSymbolName(Object->getSymbol()->getName()))
950	      JTLabel = Object->getSymbol();
951	  }
952	
953	  const uint64_t EntrySize = getJumpTableEntrySize(Type);
954	  if (!JTLabel) {
955	    const std::string JumpTableName = generateJumpTableName(Function, Address);
956	    JTLabel = registerNameAtAddress(JumpTableName, Address, 0, EntrySize);
957	  }
958	
959	  LLVM_DEBUG(dbgs() << "BOLT-DEBUG: creating jump table " << JTLabel->getName()
960	                    << " in function " << Function << '\n');
961	
962	  JumpTable *JT = new JumpTable(*JTLabel, Address, EntrySize, Type,
963	                                JumpTable::LabelMapType{{0, JTLabel}},
964	                                *getSectionForAddress(Address));
965	  JT->Parents.push_back(&Function);
966	  if (opts::Verbosity > 2)
967	    JT->print(this->outs());
968	  JumpTables.emplace(Address, JT);
969	
970	  // Duplicate the entry for the parent function for easy access.
971	  Function.JumpTables.emplace(Address, JT);
972	  return JTLabel;
973	}
